import{shatteredAdapter,readShatteredRecord,validateShatteredDataPatch}from'./shattered-adapter.js';
export function shatteredSystemsWorkshop(api){const $=s=>document.querySelector(s),esc=api.esc,reader=()=>api.session()?.reader,graph=()=>api.project().nativeStory?.[api.session()?.id];let selectedClass=0,selectedPath=1,selectedGear='hands',selectedGearId=0;
 const row=(table,id)=>{const base=readShatteredRecord(reader(),table,id);return{...base,...graph()?.edits.nativeData?.[table+':'+id]?.values};};
 const restore=(table,id)=>{api.change(()=>{if(graph()?.edits.nativeData)delete graph().edits.nativeData[table+':'+id];});api.close();api.afterChange?.();open();};
 function save(base,values){const patch={table:base.table,id:base.id,original:base.original,values};validateShatteredDataPatch(reader(),patch);const g=graph();if(!g)throw Error('Import the ROM event graph before editing its native systems.');api.change(()=>{g.edits.nativeData??={};g.edits.nativeData[base.table+':'+base.id]=patch;});api.afterChange?.();}
 function open(){const p=reader()&&shatteredAdapter(reader());if(!p)throw Error('The selected ROM does not match the verified Shattered native adapter.');const classes=Array.from({length:p.tables.classes.count},(_,i)=>row('classes',i));api.modal('Shattered native systems',`<p>Verified native tables: 171 Human classes, 17 trial paths, 5,850 learnset entries and gear catalogues. Edits change data used by the original runtime; native code is retained.</p><label>Human class<select id="shatteredClass">${classes.map(c=>`<option value="${c.id}" ${c.id===selectedClass?'selected':''}>${c.id} · ${esc(c.name)} · stage ${c.stage}</option>`).join('')}</select></label><div class="button-row"><button id="shatteredClassEdit" type="button">Edit class</button><button id="shatteredLearnEdit" type="button">Edit learnset</button></div><label>Class trial<select id="shatteredPath">${Array.from({length:17},(_,i)=>row('paths',i+1)).map(p=>`<option value="${p.id}" ${p.id===selectedPath?'selected':''}>${p.id} · ${esc(p.name)}</option>`).join('')}</select></label><button id="shatteredPathEdit" type="button">Edit trial requirements</button><label>Gear catalogue<select id="shatteredGear">${['hands','body','feet','head','accessories'].map(t=>`<option ${t===selectedGear?'selected':''}>${t}</option>`).join('')}</select></label><label>Gear<select id="shatteredGearId"></select></label><button id="shatteredGearEdit" type="button">Edit gear</button><p>Class IDs, stage/combination layout and table lengths are fixed. Current level gates remain native code: first stage 30, second stage 55. Changes affect these shared definitions globally; saves are not rewritten.</p>`,null,'Done');$('#shatteredClass').onchange=()=>selectedClass=+$('#shatteredClass').value;$('#shatteredPath').onchange=()=>selectedPath=+$('#shatteredPath').value;$('#shatteredClassEdit').onclick=()=>editClass(selectedClass);$('#shatteredLearnEdit').onclick=()=>editLearnset(selectedClass);$('#shatteredPathEdit').onclick=()=>editPath(selectedPath);const gears=()=>{$('#shatteredGearId').innerHTML=Array.from({length:p.tables[selectedGear].count},(_,i)=>row(selectedGear,i)).map(g=>`<option value="${g.id}" ${g.id===selectedGearId?'selected':''}>${g.id} · ${esc(g.name)}</option>`).join('');selectedGearId=+$('#shatteredGearId').value;};$('#shatteredGear').onchange=()=>{selectedGear=$('#shatteredGear').value;selectedGearId=0;gears();};$('#shatteredGearId').onchange=()=>selectedGearId=+$('#shatteredGearId').value;$('#shatteredGearEdit').onclick=()=>editGear(selectedGear,selectedGearId);gears();}
 const number=(id,label,value,min,max)=>`<label>${label}<input id="${id}" type="number" min="${min}" max="${max}" value="${value}"></label>`,num=id=>Number($('#'+id).value);
 function editClass(id){const base=readShatteredRecord(reader(),'classes',id),c=row('classes',id),stats=['HP','Attack','Defense','Speed','Sp. Attack','Sp. Defense'];api.modal('Human class · '+c.name,`<p>Class ${id} · stage ${c.stage} · combination ${c.a} + ${c.b}. The class identity and progression layout stay fixed.</p><label>Name<input id="shatteredName" maxlength="${base.name.length}" value="${esc(c.name)}"></label><label>Description<textarea id="shatteredDescription" maxlength="${base.description.length}">${esc(c.description)}</textarea></label><div class="field-row">${stats.map((s,i)=>number('shatteredStat'+i,s,c.stats[i],1,255)).join('')}</div><div class="field-row">${c.types.map((t,i)=>number('shatteredType'+i,'Native type '+(i+1),t,0,23)).join('')}${c.abilities.map((t,i)=>number('shatteredAbility'+i,'Passive ability ID '+(i+1),t,0,255)).join('')}</div><p>Native type IDs: 0 Normal, 1 Fighting, 2 Flying, 3 Poison, 4 Ground, 5 Rock, 6 Bug, 7 Ghost, 8 Steel, 9 Human/mystery, 10 Fire, 11 Water, 12 Grass, 13 Electric, 14 Psychic, 15 Ice, 16 Dragon, 17 Dark, 23 Fairy. Passive 0 means none. Native ability IDs remain numeric.</p><p>Text replacements use ASCII and cannot exceed the original field length.</p><button id="shatteredReset" type="button">Restore source class</button>`,()=>{save(base,{name:$('#shatteredName').value,description:$('#shatteredDescription').value,stats:stats.map((_,i)=>num('shatteredStat'+i)),types:[num('shatteredType0'),num('shatteredType1')],abilities:[num('shatteredAbility0'),num('shatteredAbility1')]});},'Save class');$('#shatteredReset').onclick=()=>restore('classes',id);}
 function editPath(id){const base=readShatteredRecord(reader(),'paths',id),p=row('paths',id);api.modal('Trial · '+p.name,`<p>${esc(p.description)}</p><p>The native eligibility check requires these two known moves. Level gates remain 30 / 55, and trial completion still requires the native battle result.</p>${number('shatteredCourse0','Course move ID 1',p.courses[0],1,990)}${number('shatteredCourse1','Course move ID 2',p.courses[1],1,990)}<button id="shatteredReset" type="button">Restore source trial</button>`,()=>save(base,{courses:[num('shatteredCourse0'),num('shatteredCourse1')]}),'Save trial');$('#shatteredReset').onclick=()=>restore('paths',id);}
 function editGear(table,id){const base=readShatteredRecord(reader(),table,id),g=row(table,id);api.modal('Gear · '+g.name,`<label>Name<input id="shatteredName" maxlength="${base.name.length}" value="${esc(g.name)}"></label><label>Description<textarea id="shatteredDescription" maxlength="${base.description.length}">${esc(g.description)}</textarea></label>${number('shatteredMove','Granted move ID (0 none)',g.move,0,990)}${number('shatteredDefense','Defense bonus',g.defense,0,255)}${number('shatteredSpeed','Speed penalty',g.speedPenalty,0,255)}${number('shatteredResist','Resist type ID (255 none)',g.resistType,0,255)}${number('shatteredAbility','Ability ID (0 none)',g.ability,0,255)}${number('shatteredPrice','Price, native units',g.price,0,255)}<p>These are the engine’s catalogue fields. Ownership and equipped slots stay in the save. Update the description if you change a bonus. Text must fit its original ASCII field length.</p><button id="shatteredReset" type="button">Restore source gear</button>`,()=>save(base,{name:$('#shatteredName').value,description:$('#shatteredDescription').value,move:num('shatteredMove'),defense:num('shatteredDefense'),speedPenalty:num('shatteredSpeed'),resistType:num('shatteredResist'),ability:num('shatteredAbility'),price:num('shatteredPrice')}),'Save gear');$('#shatteredReset').onclick=()=>restore(table,id);}
 function editLearnset(id){const p=shatteredAdapter(reader()),records=[];for(let i=0;i<p.tables.learnsets.count;i++){const r=row('learnsets',i);if(r.classId===id)records.push(r);}const c=row('classes',id);api.modal('Learnset · '+c.name,`<p>Existing ${records.length} native learnset records for class ${id}. Levels 1–100; move IDs 1–990. Record count and class ownership remain fixed.</p>${records.map(r=>`<div class="field-row">${number('learnLevel'+r.id,'Level',r.level,1,100)}${number('learnMove'+r.id,'Move ID',r.move,1,990)}</div>`).join('')}<button id="shatteredLearnReset" type="button">Restore this class’s source learnset</button>`,()=>{const patches=records.map(r=>({table:'learnsets',id:r.id,original:readShatteredRecord(reader(),'learnsets',r.id).original,values:{level:num('learnLevel'+r.id),move:num('learnMove'+r.id)}}));for(const p of patches)validateShatteredDataPatch(reader(),p);api.change(()=>{const g=graph();g.edits.nativeData??={};for(const p of patches){const base=readShatteredRecord(reader(),'learnsets',p.id);if(p.values.level===base.level&&p.values.move===base.move)delete g.edits.nativeData['learnsets:'+p.id];else g.edits.nativeData['learnsets:'+p.id]=p;}});api.afterChange?.();},'Save learnset');$('#shatteredLearnReset').onclick=()=>{api.change(()=>{for(const r of records)if(graph().edits.nativeData)delete graph().edits.nativeData['learnsets:'+r.id];});api.close();open();};}
 return{open};}
